use std::collections::HashMap;

fn solve(cafes: Vec<i8>) -> i8 {
    // Build a map from each cafe value to its last occurrence index
    let mut last_pos_map: HashMap<i8, usize> = HashMap::new();
    for (i, &v) in cafes.iter().enumerate() {
        last_pos_map.insert(v, i);
    }

    // Find the cafe whose last occurrence index is minimal
    // Since `cafes` is non-empty, `last_pos_map` is non-empty
    *last_pos_map
        .iter()
        .min_by_key(|&(_cafe, &pos)| pos)
        .unwrap()
        .0
}

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Scan from the end to find the last position of `cafe`
    for i in (0..cafes.len()).rev() {
        if cafes[i] == cafe {
            return i;
        }
    }
    // According to the problem statement, `cafe` must appear at least once.
    unreachable!("The specified cafe value does not appear in the array");
}

